package br.com.omnilog.structures; import java.util.*; public final class HistoricoOperador {private final Deque<String> pilha=new ArrayDeque<>();public void registrar(String a){if(a==null||a.isBlank())throw new IllegalArgumentException("Ação obrigatória");pilha.push(a);}public Optional<String> voltar(){return pilha.isEmpty()?Optional.empty():Optional.of(pilha.pop());}public int tamanho(){return pilha.size();}}
